cd /tmp/vally-eval-trial-3IVbTh && mkdir -p tests/CheckoutPricing.UnitTest/Features/Discount && cat > tests/CheckoutPricing.UnitTest/Features/Discount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_9500_cents_for_a_10000_cent_basket()
    {
        // AC-1 — Bronze basket
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --no-restore --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" 2>&1 | tail -25

